export type Subject =
  | "Science"
  | "Math"
  | "Computer Studies"
  | "Technical Arts"
  | "Humanities"
  | "Language"
  | "Home Economics"
  | "Bible Knowledge";

export type Difficulty = "Easy" | "Medium" | "Hard";

/**
 * Bloom's-taxonomy-inspired cognitive level.
 * "recall"      - remembering a fact or definition
 * "application" - using a rule/formula/concept on a new, concrete situation
 * "analysis"    - multi-step reasoning, interpreting data, or comparing/judging scenarios
 */
export type CognitiveLevel = "recall" | "application" | "analysis";

export interface Question {
  id: number;
  subject: Subject;
  difficulty: Difficulty;
  text: string;
  options: { label: string; value: number; text: string }[];
  explanation?: string;
  /** Defaults from `difficulty` via cognitiveLevelOf() when not set explicitly. */
  cognitiveLevel?: CognitiveLevel;
  /** Malawi secondary school textbook series this question is grounded in. */
  source?: string;
}

const DEFAULT_COGNITIVE_LEVEL: Record<Difficulty, CognitiveLevel> = {
  Easy: "recall",
  Medium: "application",
  Hard: "analysis",
};

export function cognitiveLevelOf(question: Question): CognitiveLevel {
  return question.cognitiveLevel ?? DEFAULT_COGNITIVE_LEVEL[question.difficulty];
}

export const COGNITIVE_LEVEL_LABEL: Record<CognitiveLevel, string> = {
  recall: "Recall",
  application: "Apply",
  analysis: "Analyse",
};

/** Subjects that count toward the Sciences stream */
export const SCIENCE_SUBJECTS: Subject[] = ["Science", "Math", "Computer Studies", "Technical Arts"];
/** Subjects that count toward the Humanities stream */
export const HUMANITIES_SUBJECTS: Subject[] = ["Humanities", "Language", "Home Economics", "Bible Knowledge"];

const o = (a: string, b: string, c: string, d: string, correct: 0 | 1 | 2 | 3) => {
  const texts = [a, b, c, d];
  const weights = [1, 2, 0, 1];
  return texts.map((text, i) => ({
    label: ["A", "B", "C", "D"][i],
    value: i === correct ? 4 : weights[i],
    text,
  }));
};

